import {it,expect,vi,afterEach} from 'vitest'
import {webcrypto} from 'node:crypto'
import {LoopCatalog} from './loop-catalog'
import {AudioCache,AudioBufferPool} from '../../listen-upstream/realtime/cache'
const prepare=vi.hoisted(()=>({readMetadata:vi.fn(),readMetadataBytes:vi.fn(),sliceSceneSource:vi.fn()}));vi.mock('./prepare',()=>prepare)
afterEach(()=>vi.clearAllMocks())
it('refuses modified immutable metadata before loading audio or touching cache budget',async()=>{const ctx:any={sampleRate:44100},shared=new AudioCache(ctx,new URL('https://example.test'),()=>{},new AudioBufferPool()),catalog=new LoopCatalog(ctx,shared,new URL('https://example.test'));prepare.readMetadataBytes.mockResolvedValueOnce(new TextEncoder().encode('{}').buffer);vi.stubGlobal('crypto',webcrypto);const before=shared.pool.limit;await expect(catalog.prepare({id:'a'.repeat(64),sha256:'b'.repeat(64),url:'/listen/loop-extension/v1/'+'b'.repeat(64)+'.json',trackId:'track-'+'a'.repeat(20),startFrame:441000} as any,{} as any,()=>1,new AbortController().signal)).rejects.toThrow('指纹');expect(prepare.sliceSceneSource).not.toHaveBeenCalled();expect(shared.pool.limit).toBe(before);catalog.dispose();expect(shared.pool.owners.size).toBe(1)})
it('reads only valid source-bound future entries; arbitrary metadata routes fail closed',async()=>{const ctx:any={sampleRate:44100},shared=new AudioCache(ctx,new URL('https://example.test'),()=>{}),catalog=new LoopCatalog(ctx,shared,new URL('https://example.test')),r={id:'a'.repeat(64),sha256:'b'.repeat(64),url:'/elsewhere.json',trackId:'track-'+'a'.repeat(20),startFrame:441000};prepare.readMetadata.mockResolvedValueOnce({schema:'harbeat.loop-extension-index.v1',loops:[r]});await expect(catalog.candidates({id:r.trackId} as any,1,new AbortController().signal)).rejects.toThrow('目录');r.url='/listen/loop-extension/v1/'+r.sha256+'.json';prepare.readMetadata.mockResolvedValueOnce({schema:'harbeat.loop-extension-index.v1',loops:[r]});expect(await catalog.candidates({id:r.trackId} as any,10,new AbortController().signal)).toEqual([]);catalog.dispose()})
